mapper.select:
select hba.bp_attachment_id, hba.bp_id, hba.document_name, hba.file_type, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'FILE_TYPE' and sc.code_value = hba.file_type) file_type_n, (SELECT wm_concat(fa.file_name) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE to_char(hba.bp_attachment_id) = fam.table_pk_value AND fam.table_name = 'HLS_BP_ATTACHMENT' and fa.attachment_id = fam.attachment_id) file_name, (SELECT (SELECT DISTINCT (fe. NAME) FROM sys_user_allocation sua, fnd_employee_assigns fea, fnd_employee fe WHERE fa.created_by = sua.user_id AND sua.employee_assign_id = fea.EMPLOYEE_ASSIGN_ID AND fe.EMPLOYEE_ID = fea.EMPLOYEE_ID) upload_person FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE to_char(hba.bp_attachment_id) = fam.table_pk_value AND fam.table_name = 'HLS_BP_ATTACHMENT' and fa.attachment_id = fam.attachment_id and rownum=1) upload_person, (SELECT fa.creation_date FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE to_char(hba.bp_attachment_id) = fam.table_pk_value AND fam.table_name = 'HLS_BP_ATTACHMENT' and fa.attachment_id = fam.attachment_id and rownum=1) upload_date, hba.description from hls_bp_attachment hba where 1 = 1
and hba.bp_id = #{bpId}
order by last_update_date asc

select * from( select hba.bp_attachment_id as bp_attachment_id, hba.document_name as document_name, sa.attachment_id attachment_id, sf.file_id as file_id, sf.file_name as file_name, sf.file_size as file_size, (select su.description from sys_user su where sf.last_updated_by = su.user_id) as upload_person, sf.last_update_date as uploadDate from hls_bp_attachment hba, sys_attachment sa, sys_file sf where hba.bp_attachment_id = sa.source_key and hba.bp_source_type = sa.source_type and sa.attachment_id = sf.attachment_id
and hba.bp_attachment_id = #{bpAttachmentId}
and hba.bp_id = #{bpId}
) qf order by qf.uploadDate desc
